3030   /// Checks if two instructions may access the same memory.
3031   ///
3032   /// \p Loc1 is the location of \p Inst1. It is passed explicitly because it
3033   /// is invariant in the calling loop.
3034   bool isAliased(const MemoryLocation &Loc1, Instruction *Inst1,
3035                  Instruction *Inst2) {
3036     if (!Loc1.Ptr || !isSimple(Inst1) || !isSimple(Inst2))
3037       return true;
3038     // First check if the result is already in the cache.
3039     AliasCacheKey Key = std::make_pair(Inst1, Inst2);
3040     auto It = AliasCache.find(Key);
3041     if (It != AliasCache.end())
3042       return It->second;
3043     bool Aliased = isModOrRefSet(BatchAA.getModRefInfo(Inst2, Loc1));
3044     // Store the result in the cache.
3045     AliasCache.try_emplace(Key, Aliased);
3046     AliasCache.try_emplace(std::make_pair(Inst2, Inst1), Aliased);
3047     return Aliased;
3048   }
